'use client';
import { useRef, useState, type CSSProperties, type PointerEvent } from 'react';
import { cx } from '../lib/cx';
import { useControllable, useIsoLayoutEffect, useReducedMotion, useTween } from '../lib/hooks';
import { Icon } from '../lib/icons';
import { enter, Fold, Seg, Swap, Think, Tip } from '../lib/motion';
import '../designme.css';
// its menus' rows glide in Clean
import '../lib/glide';
import './metric-insight.css';

export interface MetricRange {
  /** Identifies the range, like '30' */
  key: string;
  /** The switch label, like "30d" */
  label: string;
  /** The values over the range, oldest first */
  points: number[];
  /** The number in large type, which rolls to it */
  value: number;
  /** The change over the range, in the tag beside it */
  change: number;
  /** One line on what happened, like "Jumped after the pricing page update on Sep 18." */
  insight: string;
  /** A marker on the chart, like a release: `at` is 0 to 1 across, `tag` is the short label on the chart (like "Sep 18"),
   *  and `label` shows on hover */
  marker?: { at: number; label: string; tag?: string };
}

export interface MetricDriver {
  label: string;
  /** Its share of the change, 0 to 100 */
  percent: number;
  /** Its bar's colour, any CSS colour. Defaults to the accent's mark colour; give what the agent could not explain a grey,
   *  like 'var(--dm-muted)'. The names tell the drivers apart, so they need no colour of their own */
  color?: string;
}

export interface MetricInsightProps {
  /** The metric's name, like "Trial to paid" */
  label: string;
  ranges: MetricRange[];
  /** The range on show, by key. Leave it out to let the switch pick it */
  range?: string;
  defaultRange?: string;
  onRangeChange?: (key: string) => void;
  /** Formats the large number and the hovered point. Defaults to one decimal and a % */
  format?: (value: number) => string;
  /** Formats the change. Defaults to "+8.1 pts" */
  formatChange?: (change: number) => string;
  /** What moved the number, shown under "Why did it move?" */
  drivers?: MetricDriver[];
  /** Shows "Looking into it" on the button, its words shimmering, and keeps the breakdown shut, while you fetch the drivers */
  explaining?: boolean;
  /** Whether the breakdown is open. Leave it out to let the button toggle it */
  open?: boolean;
  defaultOpen?: boolean;
  onOpenChange?: (open: boolean) => void;
  className?: string;
}

const pct = (v: number) => v.toFixed(1) + '%';
const pts = (v: number) => (v < 0 ? '−' : '+') + Math.abs(v).toFixed(1) + ' pts';
const W = 300, H = 90;

/** A metric with its trend, a one-line explanation, and a breakdown of what moved it. The chart follows the accent, and each
 *  driver is a bar in the accent on a neutral track. */
export function MetricInsight({ label, ranges, range, defaultRange, onRangeChange, format = pct, formatChange = pts, drivers, explaining = false, open, defaultOpen = false, onOpenChange, className }: MetricInsightProps) {
  const [key, setKey] = useControllable(range, defaultRange ?? ranges[0]?.key ?? '', onRangeChange);
  const [isOpen, setOpen] = useControllable(open, defaultOpen, onOpenChange);
  const r = ranges.find(x => x.key === key) ?? ranges[0];
  const value = useTween(r?.value ?? 0, 900, 0), change = useTween(r?.change ?? 0, 900, 0);
  const [hover, setHover] = useState<{ x: number; y: number; px: number; py: number; v: number } | null>(null);

  // the chart, scaled to 300 by 90 with a point of room above and below
  const d = r?.points ?? [];
  const lo = Math.min(...d) - 1, hi = Math.max(...d) + 1;
  const xy = d.map((v, i) => [d.length > 1 ? i / (d.length - 1) * W : 0, 86 - (v - lo) / (hi - lo) * 80, v] as const);
  const path = xy.map((q, i) => (i ? 'L' : 'M') + q[0].toFixed(1) + ' ' + q[1].toFixed(1)).join(' ');

  // the area and the marker fade in once the metric appears; a range change redraws the line in place
  const chart = useRef<HTMLDivElement>(null);
  useIsoLayoutEffect(() => {
    const el = chart.current; if (!el) return;
    void el.offsetWidth;
    const id = requestAnimationFrame(() => el.classList.add('dm-in'));
    return () => cancelAnimationFrame(id);
  }, []);

  const move = (e: PointerEvent<HTMLDivElement>) => {
    if (!xy.length) return;
    const b = e.currentTarget.getBoundingClientRect(), fx = (e.clientX - b.left) / b.width * W;
    let best = xy[0]; xy.forEach(q => { if (Math.abs(q[0] - fx) < Math.abs(best[0] - fx)) best = q; });
    setHover({ x: best[0], y: best[1], px: best[0] / W * b.width, py: best[1] / H * b.height, v: best[2] });
  };

  const shown = isOpen && !explaining && !!drivers?.length;
  // the button is as wide as its words: a new label comes in and its width eases to fit (no room kept for a longer one)
  const why = useRef<HTMLButtonElement>(null), whyW = useRef(0), reduce = useReducedMotion();
  const words = explaining ? 'Looking into it' : shown ? 'Hide the breakdown' : 'Why did it move?';
  useIsoLayoutEffect(() => {
    const el = why.current; if (!el) return;
    const w0 = whyW.current, w1 = el.getBoundingClientRect().width; whyW.current = w1;
    if (!reduce && w0 && Math.abs(w1 - w0) > .5 && typeof el.animate === 'function') {
      const cs = getComputedStyle(el), t = cs.getPropertyValue('--dm-t').trim();
      el.animate([{ width: w0 + 'px' }, { width: w1 + 'px' }], { duration: (t.endsWith('ms') ? parseFloat(t) : parseFloat(t) * 1000) || 340, easing: cs.getPropertyValue('--dm-ease').trim() || 'ease' });
    }
  }, [words]);
  const [opened, setOpened] = useState(0);
  const [wasShown, setWasShown] = useState(shown);
  if (shown !== wasShown) { setWasShown(shown); if (shown) setOpened(n => n + 1); }

  return (
    <div data-dm="" className={cx('dm-mix dm-panel', className)}>
      <div className="dm-mix-h">
        <span className="dm-muted">{label}</span>
        <Seg className="dm-mix-rg" label="Range" value={key} onChange={setKey} options={ranges.map(x => ({ value: x.key, label: x.label }))} />
      </div>
      <div className="dm-mix-v">
        <b className="dm-num dm-mix-n">{format(hover ? hover.v : value)}</b>
        <span className={cx('dm-tag dm-mix-d dm-num', (r?.change ?? 0) < 0 ? 'dm-bad' : 'dm-ok')}>{formatChange(change)}</span>
      </div>
      <div className="dm-mix-ch" ref={chart} onPointerMove={move} onPointerLeave={() => setHover(null)}>
        <svg className="dm-mix-svg" viewBox={`0 0 ${W} ${H}`} preserveAspectRatio="none" aria-hidden="true">
          <defs><linearGradient id="dm-mixg" x1="0" x2="0" y1="0" y2="1"><stop offset="0" stopColor="var(--dm-accent-mark,var(--dm-accent))" stopOpacity=".18" /><stop offset="1" stopColor="var(--dm-accent-mark,var(--dm-accent))" stopOpacity="0" /></linearGradient></defs>
          <path className="dm-mix-a" fill="url(#dm-mixg)" d={path && path + ` L${W} ${H} L0 ${H} Z`} />
          <path className="dm-mix-l" fill="none" stroke="var(--dm-accent-mark,var(--dm-accent))" strokeWidth={2} vectorEffect="non-scaling-stroke" strokeLinejoin="round" d={path} />
          <line className="dm-mix-x" x1={hover?.x ?? 0} x2={hover?.x ?? 0} y1={0} y2={H} stroke="var(--dm-faint)" strokeDasharray="2 3" vectorEffect="non-scaling-stroke" />
        </svg>
        <span className="dm-mix-dot" style={hover ? { left: hover.px, top: hover.py } : undefined} />
        {r?.marker && <Marker key={r.key} at={r.marker.at} label={r.marker.label} tag={r.marker.tag} />}
      </div>
      <div className="dm-mix-ins"><span className="dm-mix-ic"><Icon name="spark" size="xs" /></span><Swap className="dm-mix-t">{r?.insight ?? ''}</Swap></div>
      {drivers && (
        <button ref={why} type="button" className="dm-pill dm-line dm-sm dm-mix-why" aria-expanded={shown} onClick={() => { if (!explaining) setOpen(!isOpen); }}>
          {/* while the agent looks into it, its words shimmer */}
          {explaining && <Think />}
          <span className={explaining ? 'dm-shim' : undefined}>{words}</span>
        </button>
      )}
      {drivers && (
        <Fold open={shown} className="dm-mix-box">
          <div className="dm-mix-rs" key={opened}>
            {drivers.map((q, i) => {
              const e = enter(i * 60);
              return (
                <div key={q.label + i} className={cx('dm-mix-r', e.className)} style={e.style}>
                  <span className="dm-t">{q.label}</span>
                  <span className="dm-bar"><i style={{ width: q.percent + '%', ...(q.color ? { '--dm-k': q.color } : {}) } as CSSProperties} /></span>
                  <span className="dm-v dm-num">{q.percent}%</span>
                </div>
              );
            })}
          </div>
        </Fold>
      )}
    </div>
  );
}

/** The marker on the chart: a small label at the top of a dashed guide down through the chart, where the change happened.
 *  It fades in late, after the line, each time a range that has one comes up */
function Marker({ at, label, tag }: { at: number; label: string; tag?: string }) {
  const ref = useRef<HTMLSpanElement>(null);
  // it renders hidden, then lets the stylesheet take over a frame later, so the delayed fade-in runs
  useIsoLayoutEffect(() => {
    const el = ref.current; if (!el) return;
    void el.offsetWidth;
    const id = requestAnimationFrame(() => { el.style.opacity = ''; });
    return () => cancelAnimationFrame(id);
  }, []);
  return <span ref={ref} className="dm-mix-mk" style={{ left: at * 100 + '%', opacity: 0 }}><Tip label={label}><b><Icon name="spark" size="xs" />{tag}</b></Tip></span>;
}

/* Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync. */
/* ---------- Metric insight ---------- */
/* one number, its trend over the range, and the agent's read on why it moved. Its content sits 16px from every edge (owner,
   18 Nov), the range switch ending on the content's right edge. The chart follows the accent: its line in the accent's mark
   colour over a faint wash of it. Asked why, the button's words shimmer while the agent looks, and the drivers come in once
   it has found them, each as a bar in the accent on a neutral track (a grey one for what it could not explain): their names
   say which is which, so they need no colour of their own */
.dm-mix{padding:16px;display:flex;flex-direction:column;gap:10px}
.dm-mix-h{display:flex;align-items:center;justify-content:space-between;font-size:12.5px}
.dm-mix-rg button{font-size:11.5px;padding:0 var(--dm-s-2);height:24px}
.dm-mix-v{display:flex;align-items:center;gap:var(--dm-s-2)}
.dm-mix-v b{font-size:14px;font-weight:500;letter-spacing:-.02em}
.dm-mix-ch{position:relative;height:90px;cursor:crosshair}
.dm-mix-svg{width:100%;height:100%;display:block;overflow:visible}
.dm-mix-l{stroke-dasharray:var(--dm-len);stroke-dashoffset:var(--dm-len);transition:stroke-dashoffset 1.2s var(--dm-ease)}
.dm-mix-ch.dm-in .dm-mix-l{stroke-dashoffset:0}
.dm-mix-a{opacity:0;transition:opacity .8s .5s}
.dm-mix-ch.dm-in .dm-mix-a{opacity:1}
.dm-mix-x{opacity:0;transition:opacity .2s}
@media (hover:hover) and (pointer:fine){.dm-mix-ch:hover .dm-mix-x,.dm-mix-ch:hover .dm-mix-dot{opacity:1}}
.dm-mix-dot{position:absolute;width:9px;height:9px;margin:-4.5px;border-radius:50%;background:var(--dm-surface);box-shadow:0 0 0 2px var(--dm-accent-mark,var(--dm-accent));opacity:0;transition:opacity .2s;pointer-events:none}
/* the change it explains is marked where it happened: a small date label at the top of a dashed guide down through the chart */
.dm-mix-mk{position:absolute;top:-14px;bottom:0;display:flex;flex-direction:column;align-items:center;transform:translateX(-50%);opacity:0;transition:opacity .4s 1.1s;pointer-events:none}
.dm-mix-mk b{pointer-events:auto;display:inline-flex;align-items:center;gap:var(--dm-s-1);height:20px;padding:0 7px;border-radius:var(--dm-r-pill);background:var(--dm-surface);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-line) 50%,transparent);font-size:11.5px;font-weight:500;color:var(--dm-fg2);white-space:nowrap}
.dm-mix-mk b svg{width:10px;height:10px;color:var(--dm-accent-fg,var(--dm-accent))}
.dm-mix-mk::after{content:"";flex:1;border-left:1px dashed color-mix(in srgb,var(--dm-faint) 50%,transparent)}
.dm-mix-ch.dm-in .dm-mix-mk{opacity:1}
.dm-mix-ins{display:flex;gap:var(--dm-s-2);align-items:flex-start;font-size:13px;line-height:1.5;color:var(--dm-fg2)}
.dm-mix-ic{color:var(--dm-accent-fg,var(--dm-accent));display:grid;margin-top:2px}
.dm-mix-why{align-self:flex-start;overflow:hidden}
.dm-mix-why .dm-shim{font-size:inherit}
/* nothing in it grows or shrinks when it is pressed (owner, 18 Nov) */
.dm-mix :is(.dm-pill,.dm-ib):active{transform:none}
/* the reasons fold open under Why did it move?; shut, the fold takes back the card's 10px gap, so the card's content ends 16px
   from its bottom like everywhere else (owner, 21 Nov), and open, the reasons bring that room back with them */
.dm-mix-box{margin-top:-10px}
.dm-mix-rs{display:flex;flex-direction:column;gap:6px;padding-top:12px}
.dm-mix-r{display:flex;align-items:center;gap:10px;font-size:12.5px}
.dm-mix-r .dm-t{flex:1;min-width:0}
.dm-mix-r .dm-bar{width:70px;height:5px;border-radius:var(--dm-r-tiny,3px);background:var(--dm-line);overflow:hidden;flex:none}
.dm-mix-r .dm-bar i{display:block;height:100%;border-radius:var(--dm-r-tiny,3px);background:var(--dm-k,var(--dm-accent-mark,var(--dm-accent)));transform-origin:left;animation:dm-ssrel .8s var(--dm-ease) both}
.dm-mix-r .dm-v{width:44px;text-align:right;font-size:12px;color:var(--dm-fg2)}
@keyframes dm-ssrel{from{transform:scaleX(0)}}
